for(const [id,prefix] of [['nc-admissao','hr-nc'],['edit-colab-admissao','hr-ec']])$(id).addEventListener('change',()=>{$(prefix+'-date').min=value(id);if($(prefix+'-box').dataset.firstSalary==='true'||!value(prefix+'-date'))$(prefix+'-date').value=value(id);});
